return items.map((item) => {
  const b = item.json.body || item.json;
  const idCandidato = String(b.id_candidato || '').trim();
  const eleitorId = String(b.eleitor_id || b.telefone || '').trim();
  return {
    json: {
      id_candidato: idCandidato,
      evento_id: String(b.evento_id || '').trim(),
      eleitor_id: eleitorId,
      eleitor_uid: `${idCandidato}:${eleitorId}`,
      status_participacao: String(b.status_participacao || 'interessado').trim(),
      canal_registro: String(b.canal_registro || 'whatsapp').trim(),
      origem_registro: String(b.origem_registro || 'eleitor').trim(),
      lider_responsavel_id: String(b.lider_responsavel_id || '').trim(),
      observacao: String(b.observacao || '').trim(),
      metadata: b
    }
  };
});
